script:
(function () {
  'use strict';

  var btnInPhase = document.getElementById('btnInPhase');
  var btnOutPhase = document.getElementById('btnOutPhase');
  var btnStop = document.getElementById('btnStop');
  var volumeSlider = document.getElementById('volumeSlider');
  var volumeValue = document.getElementById('volumeValue');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var toolError = document.getElementById('toolError');
  var signalSelect = document.getElementById('signalSelect');
  var statExpect = document.getElementById('statExpect');
  var statSignal = document.getElementById('statSignal');
  var statRightCh = document.getElementById('statRightCh');
  var statBass = document.getElementById('statBass');
  var statCenter = document.getElementById('statCenter');
  var ifOpposite = document.getElementById('ifOpposite');

  var MAX_GAIN = 0.35; // conservative ceiling -- see this site's safety notes for playback tools
  var RAMP_SECONDS = 0.03;
  var SIGNALS = {
    tone_80: { label: '80 Hz tone', freq: 80, level: 1 },
    tone_75: { label: '75 Hz tone', freq: 75, level: 1 },
    tone_110: { label: '110 Hz tone', freq: 110, level: 1 },
    tone_440: { label: '440 Hz tone', freq: 440, level: 1 },
    rumble: { label: 'Rumble', level: 0.7 },
    guitar: { label: 'Guitar', level: 0.8 },
    pink_noise: { label: 'Pink noise', level: 0.5 }
  };

  var Ctor = window.AudioContext || window.webkitAudioContext;
  var audioCtx = null;
  var master = null, gainL = null, gainR = null;
  var source = null, env = null;
  var buffers = {};
  var playing = false;
  var inPhase = true;

  function showError(msg) {
    if (!toolError) return;
    toolError.textContent = msg;
    toolError.classList.add('show');
  }
  function clearError() {
    if (!toolError) return;
    toolError.textContent = '';
    toolError.classList.remove('show');
  }

  function setDiagnostic(sev, html) {
    diagnosticPanel.innerHTML = '<div class="diagnostic-item' + (sev ? ' sev-' + sev : '') + '"><span class="diag-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
      '</span><span>' + html + '</span></div>';
  }

  function currentGainTarget() {
    return (parseFloat(volumeSlider.value) / 100) * MAX_GAIN;
  }
  function currentSignal() {
    return SIGNALS[signalSelect.value] || SIGNALS.tone_80;
  }

  // One shared mono source split into two gain chains, routed to exact
  // left/right outputs through a ChannelMerger -- a single source
  // guarantees the two channels are perfectly correlated to start with, so
  // setting the right channel's gain to -1 is a clean, genuine phase
  // inversion rather than two independently-drifting sources.
  function ensureGraph() {
    if (!Ctor) {
      showError('Your browser doesn’t support the Web Audio API, so the polarity test can’t play here.');
      return Promise.reject(new Error('no-webaudio'));
    }
    if (!audioCtx) {
      try {
        audioCtx = new Ctor();
      } catch (e) {
        showError('The browser refused to start audio output: ' + (e && e.message ? e.message : e));
        return Promise.reject(e);
      }
      buffers = {};
      master = audioCtx.createGain();
      master.gain.value = 0;
      gainL = audioCtx.createGain();
      gainR = audioCtx.createGain();
      gainL.gain.value = 1;
      gainR.gain.value = 1;
      var merger = audioCtx.createChannelMerger(2);
      gainL.connect(merger, 0, 0);
      gainR.connect(merger, 0, 1);
      merger.connect(master);
      master.connect(audioCtx.destination);
    }
    return audioCtx.resume().then(function () { return audioCtx; }, function () { return audioCtx; });
  }

  // ---------- Signal buffers (generated locally, no downloads) ----------
  function normalise(d) {
    var peak = 0, i;
    for (i = 0; i < d.length; i++) { var a = Math.abs(d[i]); if (a > peak) peak = a; }
    if (!peak) return;
    for (i = 0; i < d.length; i++) d[i] *= 0.9 / peak;
  }

  function pinkInto(d) {
    var b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
    for (var i = 0; i < d.length; i++) {
      var w = Math.random() * 2 - 1;
      // Paul Kellet's refined pink filter: equal energy per octave.
      b0 = 0.99886 * b0 + w * 0.0555179;
      b1 = 0.99332 * b1 + w * 0.0750759;
      b2 = 0.96900 * b2 + w * 0.1538520;
      b3 = 0.86650 * b3 + w * 0.3104856;
      b4 = 0.55000 * b4 + w * 0.5329522;
      b5 = -0.7616 * b5 - w * 0.0168980;
      d[i] = b0 + b1 + b2 + b3 + b4 + b5 + b6 + w * 0.5362;
      b6 = w * 0.115926;
    }
  }

  // Karplus-Strong plucked string: a short noise burst recirculated through
  // an averaging filter -- a guitar-like pluck with no recording needed.
  function pluck(d, sr, at, freq, amp) {
    var start = Math.round(at * sr);
    var n = Math.max(2, Math.round(sr / freq));
    var ring = new Float32Array(n);
    var prev = 0, i;
    for (i = 0; i < n; i++) { var w = Math.random() * 2 - 1; prev = 0.5 * (w + prev); ring[i] = prev; }
    var len = Math.min(d.length - start, Math.round(sr * 2.4));
    var idx = 0;
    for (i = 0; i < len; i++) {
      var cur = ring[idx];
      ring[idx] = 0.4975 * (cur + ring[(idx + 1) % n]);
      d[start + i] += cur * amp;
      idx = (idx + 1) % n;
    }
  }

  function getBuffer(kind) {
    if (buffers[kind]) return buffers[kind];
    var sr = audioCtx.sampleRate;
    var len = sr * 4;
    var buf = audioCtx.createBuffer(1, len, sr);
    var d = buf.getChannelData(0);
    var i;
    if (kind === 'pink_noise') {
      pinkInto(d);
    } else if (kind === 'rumble') {
      // Pink noise through four cascaded one-pole low-pass stages (~120 Hz).
      pinkInto(d);
      var a = Math.exp(-2 * Math.PI * 120 / sr);
      for (var stage = 0; stage < 4; stage++) {
        var y = 0;
        for (i = 0; i < len; i++) { y = (1 - a) * d[i] + a * y; d[i] = y; }
      }
    } else if (kind === 'guitar') {
      var em = [82.41, 123.47, 164.81, 196.0, 246.94, 329.63];
      var am = [110.0, 164.81, 220.0, 277.18, 329.63];
      pluck(d, sr, 0, 82.41, 0.9);
      em.forEach(function (f, k) { pluck(d, sr, 0.02 + k * 0.018, f, 0.35); });
      pluck(d, sr, 1.0, 82.41, 0.8);
      pluck(d, sr, 1.5, 123.47, 0.5);
      pluck(d, sr, 2.0, 110.0, 0.9);
      am.forEach(function (f, k) { pluck(d, sr, 2.02 + k * 0.018, f, 0.35); });
      pluck(d, sr, 3.0, 110.0, 0.8);
      pluck(d, sr, 3.5, 164.81, 0.5);
      // Fade the tail so the loop point doesn't click.
      var fade = Math.round(sr * 0.08);
      for (i = 0; i < fade; i++) d[len - 1 - i] *= i / fade;
    }
    normalise(d);
    buffers[kind] = buf;
    return buf;
  }

  // ---------- Playback ----------
  function rampTo(param, target, seconds) {
    var now = audioCtx.currentTime;
    param.cancelScheduledValues(now);
    param.setValueAtTime(param.value, now);
    param.linearRampToValueAtTime(target, now + (seconds || RAMP_SECONDS));
  }

  function releaseSource() {
    if (!source || !audioCtx) { source = null; env = null; return; }
    var s = source, e = env;
    source = null;
    env = null;
    rampTo(e.gain, 0);
    setTimeout(function () {
      try { s.stop(); } catch (err) {}
      try { s.disconnect(); e.disconnect(); } catch (err) {}
    }, RAMP_SECONDS * 1000 + 30);
  }

  function startSource() {
    releaseSource();
    var key = signalSelect.value;
    var sig = currentSignal();
    env = audioCtx.createGain();
    env.gain.value = 0;
    env.connect(gainL);
    env.connect(gainR);
    if (sig.freq) {
      source = audioCtx.createOscillator();
      source.type = 'sine';
      source.frequency.value = sig.freq;
    } else {
      source = audioCtx.createBufferSource();
      source.buffer = getBuffer(key);
      source.loop = true;
    }
    source.connect(env);
    source.start();
    rampTo(env.gain, sig.level);
  }

  function updateOutputs() {
    statSignal.textContent = playing ? currentSignal().label : '—';
    if (!playing) {
      statExpect.textContent = '—';
      statRightCh.textContent = '—';
      statBass.textContent = '—';
      statCenter.textContent = '—';
      ifOpposite.textContent = 'Play both versions back to back first.';
      return;
    }
    statExpect.textContent = inPhase ? 'Fuller, focused' : 'Thin, diffuse';
    statRightCh.textContent = inPhase ? 'Normal' : 'Inverted';
    statBass.textContent = inPhase ? 'Strong, full body' : 'Weak, thin';
    statCenter.textContent = inPhase ? 'Between speakers' : 'Hollow, vague';
    ifOpposite.textContent = inPhase
      ? 'If this version sounds thinner than out-of-phase, one speaker is wired backwards.'
      : 'If this version sounds fuller than in-phase, one speaker is wired backwards.';
  }

  function play(nextInPhase) {
    ensureGraph().then(function () {
      clearError();
      if (!source) startSource();
      playing = true;
      inPhase = nextInPhase;
      rampTo(master.gain, currentGainTarget());
      // gainR ramps through zero to -1, so switching versions mid-signal never clicks.
      rampTo(gainR.gain, inPhase ? 1 : -1, 0.04);
      btnInPhase.classList.toggle('active', inPhase);
      btnOutPhase.classList.toggle('active', !inPhase);
      btnStop.disabled = false;
      updateOutputs();
      setDiagnostic('ok', inPhase
        ? '<strong>Playing in-phase.</strong> This is how correctly wired speakers should sound — centred, with solid bass.'
        : '<strong>Playing out-of-phase (simulated reversed wiring).</strong> Notice how the sound feels diffuse and the bass thins out compared to in-phase.');
    }).catch(function (e) {
      if (e && e.message === 'no-webaudio') return;
      showError('Audio could not start: ' + (e && e.message ? e.message : e));
    });
  }

  function stop() {
    playing = false;
    if (master && audioCtx) rampTo(master.gain, 0);
    releaseSource();
    btnInPhase.classList.remove('active');
    btnOutPhase.classList.remove('active');
    btnStop.disabled = true;
    updateOutputs();
    setDiagnostic('', 'Stopped.');
  }

  btnInPhase.addEventListener('click', function () { play(true); });
  btnOutPhase.addEventListener('click', function () { play(false); });
  btnStop.addEventListener('click', stop);

  signalSelect.addEventListener('change', function () {
    if (playing && audioCtx) startSource();
    updateOutputs();
  });

  volumeSlider.addEventListener('input', function () {
    volumeValue.textContent = volumeSlider.value + '%';
    if (playing && audioCtx) rampTo(master.gain, currentGainTarget(), 0.05);
  });

  window.addEventListener('pagehide', function () {
    playing = false;
    source = null;
    env = null;
    if (audioCtx) { audioCtx.close().catch(function () {}); audioCtx = null; }
    master = gainL = gainR = null;
  });
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden' && audioCtx) {
      if (playing) stop();
      if (audioCtx.state === 'running') audioCtx.suspend().catch(function () {});
    }
  });

  if (!Ctor) {
    setDiagnostic('error', '<strong>Your browser doesn’t support the Web Audio API.</strong>');
    btnInPhase.disabled = true;
    btnOutPhase.disabled = true;
  }
})();
